constructor(config: CorsConfig = inject(CorsConfig)) {
    if (!this.isEnabled(config)) return;

    const HonoCorsMiddleware = fromHonoMiddleware(
      cors({
        origin: config.origin,
        allowMethods: config.allowMethods,
        allowHeaders: config.allowHeaders,
        exposeHeaders: config.exposeHeaders,
        ...(config.maxAge !== undefined && { maxAge: config.maxAge }),
        credentials: config.credentials,
      }),
    );
    this.delegate = new HonoCorsMiddleware();
  }

async use(next: Next, res = response()): Promise<Response | undefined> {
    await next();
    this.applyHeader(
      res,
      'Cross-Origin-Embedder-Policy',
      this.config.crossOriginEmbedderPolicy,
      'require-corp',
    );
    this.applyHeader(
      res,
      'Cross-Origin-Resource-Policy',
      this.config.crossOriginResourcePolicy,
      'same-origin',
    );
    this.applyHeader(
      res,
      'Cross-Origin-Opener-Policy',
      this.config.crossOriginOpenerPolicy,
