constructor(lifecycle = inject(LifecycleManager)) {
    this.sqlite = new Database(':memory:');
    this.sqlite.pragma('foreign_keys = ON');
    this.db = drizzle(this.sqlite, { schema });
    this.initSchema();
    lifecycle.register(this);
  }

private initSchema() {
    this.sqlite.exec(`
      CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        email TEXT NOT NULL UNIQUE,
        password_hash TEXT NOT NULL,
        name TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user',
        created_at INTEGER NOT NULL
      );

      CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        description TEXT NOT NULL,
        price INTEGER NOT NULL,
        category TEXT NOT NULL,
        stock INTEGER NOT NULL DEFAULT 0,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
      );

      CREATE TABLE IF NOT EXISTS orders (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL REFERENCES users(id),
        status TEXT NOT NULL DEFAULT 'pending',
        total_price INTEGER NOT NULL,
        created_at INTEGER NOT NULL
      );

      CREATE TABLE IF NOT EXISTS order_items (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        order_id INTEGER NOT NULL REFERENCES orders(id),
        product_id INTEGER NOT NULL REFERENCES products(id),
        quantity INTEGER NOT NULL,
        unit_price INTEGER NOT NULL
      );
    `);
  }

async shutdown(): Promise<void> {
    this.sqlite.close();
  }

namespace<const S extends string>(prefix: NonEmptyString<S>): AtomicKVStore {
    return new MemoryKVStore(this.data, prefix, this.util);
  }

async get<T>(key: string): Promise<T | undefined> {
    const entry = this.current(key);
    return entry ? this.util.deserialize<T>(entry.raw) : undefined;
  }

async set<T extends Defined>(key: string, value: T, opts?: SetOptions): Promise<void> {
    validateTtl(opts?.ttlSec);
    const raw = this.util.serialize(value);
    this.data.set(this.k(key), makeEntry(raw, opts?.ttlSec));
  }

async del(key: string): Promise<void> {
    this.data.delete(this.k(key));
  }

async emit<K extends string & keyof EventBusSchema>(
    event: K,
    data: EventBusSchema[K],
  ): Promise<void> {
    this.emitter.emit(event, data);
  }

on<K extends string & keyof EventBusSchema>(
    event: K,
    handler: (data: EventBusSchema[K]) => void,
  ): () => void {
    this.emitter.on(event, handler);
    return () => this.emitter.off(event, handler);
  }

once<K extends string & keyof EventBusSchema>(
    event: K,
    handler: (data: EventBusSchema[K]) => void,
  ): () => void {
    const wrappedHandler = (data: EventBusSchema[K]) => {
      unsubscribe();
      handler(data);
    };
    const unsubscribe = this.on(event, wrappedHandler);
    return unsubscribe;
  }

async sign(payload: Record<string, unknown>): Promise<string> {
    const secret = new TextEncoder().encode(this.config.secret);
    const expiresIn = this.parseExpiresIn(this.config.expiresIn);

    const jwt = await new SignJWT(payload)
      .setProtectedHeader({ alg: 'HS256' })
      .setIssuedAt()
      .setExpirationTime(expiresIn)
      .sign(secret);

    return jwt;
  }

async verify(token: string): Promise<JwtPayload> {
    const secret = new TextEncoder().encode(this.config.secret);
    const { payload } = await jwtVerify<JwtPayload>(token, secret);
    return payload;
  }

decode(token: string): JwtPayload | null {
    try {
      return decodeJwt<JwtPayload>(token);
    } catch {
      return null;
    }
  }

private parseExpiresIn(expiresIn: string): string | number {
    const match = /^(\d+)([smhd])$/.exec(expiresIn);
    if (match) {
      const value = parseInt(match[1] ?? '0', 10);
      const unit = match[2] ?? '';
      const unitMap: Record<string, string> = {
        s: 'seconds',
        m: 'minutes',
        h: 'hours',
        d: 'days',
      };
      return `${value} ${unitMap[unit]}`;
    }
    return expiresIn;
  }

info(msg: string, ctx: LogContext = {}): void {
    this.log('info', msg, ctx);
  }

async hit(
    key: string,
    opts?: { limit?: number; windowSec?: number },
  ): Promise<RateLimiterHitResult> {
    const limit = opts?.limit ?? this.config.defaultLimit;
    const windowSec = opts?.windowSec ?? this.config.defaultWindowSec;

    try {
      const count = await this.store.incr(key, 1, { ttlSec: windowSec });
      return { ok: true, value: this.buildResult(count, limit, windowSec) };
    } catch (err) {
      return this.handleKVError(err, key, limit);
    }
  }

register(lifecycle: Lifecycle<unknown>): ReadyValue<object> | undefined {
    const readyValue = createReadyValue<object>();
    this.lifecycles.push({ lc: lifecycle, readyValue });
    return readyValue;
  }

